import {createCloudAccount} from './cloud-account.mjs';
import {renderChapter,noteStats,noteAttribution,lessonPlainText} from './note-reader.mjs';
import {createLearningTools} from './learning-ui.mjs';
import {courses,cards as seedCards,lessons,sources,stations,verifiedOn,anatomyOutcomes} from './content.mjs';
import {defaults,dayKey,DAY,scheduleCard,shuffle,interleave,reviewQueue,recordMistake,validateBackup,selectStudyCards} from './core.mjs';

const KEY='physio-study-desk-v1';
const $=s=>document.querySelector(s);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=p=>`${p}-${crypto.randomUUID()}`;
let state=defaults(),storageBlocked=false,loadError='',lastPersisted=null;
try{lastPersisted=localStorage.getItem(KEY);if(lastPersisted)state=validateBackup(JSON.parse(lastPersisted));}catch{storageBlocked=true;loadError='Your saved data could not be read. It has been left untouched. Export the stored file in Settings before replacing it.';}
let session=null,quiz=null,toastTimeout,noteTab='library',stationId=null,importCandidate=null,pendingSessionStart=null;
const main=$('#main'),modal=$('#modal');
const iconNames={guided:'cards',outcomes:'book-open',diagrams:'books',today:'house',courses:'book-open',recall:'cards',quiz:'check-square',mistakes:'clock-counter-clockwise',notes:'notebook',practice:'clipboard-text',resources:'books',planner:'calendar-blank',progress:'chart-bar',settings:'gear',account:'gear',arrow:'arrow-right',external:'arrow-up-right',reset:'arrow-counter-clockwise',caret:'caret-down',close:'x',plus:'plus'};
const navItems=[['guided','Guided study'],['outcomes','Learning outcomes'],['diagrams','Diagram practice'],['today','Today'],['courses','My courses'],['recall','Spaced recall'],['quiz','Quick quiz'],['mistakes','Mistake review'],['notes','Study notes'],['practice','Practical prep'],['resources','Source library'],['planner','Study planner'],['progress','My progress'],['account','Account & sync']];
const icon=name=>`<img class="ui-icon" src="./assets/icons/${iconNames[name]||'notebook'}.svg" alt="" width="20" height="20" aria-hidden="true">`;
const allCards=()=>[...seedCards,...state.customCards];
const courseName=id=>courses.find(c=>c.id===id)?.title||id;
const cardById=id=>allCards().find(c=>c.id===id);
const activeCourses=()=>courses.filter(c=>c.year===state.settings.year&&c.semester===state.settings.semester&&(c.stream==='both'||c.stream===state.settings.stream));
const currentCards=()=>allCards().filter(c=>activeCourses().some(a=>a.id===c.course));
const matches=(text,query)=>text.toLowerCase().includes(query.toLowerCase());

function persistActive(write=true){
  const kind=session?'recall':quiz?'quiz':null;if(!kind)return false;
  const learning=state.learning;
  const data=session?{kind,cardIds:session.cards.map(c=>c.id),index:session.index,revealed:session.revealed,practice:session.practice,ratings:session.ratings,course:session.course||'',draft:session.draft||''}:{kind,items:quiz.cards.map(c=>({id:c.id,order:c.options.map(o=>o.correct?0:c.wrong.indexOf(o.text)+1)})),index:quiz.index,selected:quiz.selected,answers:quiz.answers};
  const complete=data.index>=(session?session.cards.length:quiz.cards.length);
  if(complete){if(!learning[kind])return false;learning[kind]=null;learning.resume=[learning.recall,learning.quiz].filter(Boolean).sort((a,b)=>b.updated-a.updated)[0]||null;if(write)save();return true;}
  const old=learning[kind];if(old&&JSON.stringify({...old,updated:0})===JSON.stringify({...data,updated:0}))return false;
  learning[kind]={...data,updated:Date.now()};learning.resume=learning[kind];if(write)save();return true;
}
function resumeSession(kind=state.learning.resume?.kind){
  const r=state.learning[kind]||(state.learning.resume?.kind===kind?state.learning.resume:null);if(!r)return;
  const ids=r.kind==='recall'?r.cardIds:r.items.map(x=>x.id);if(ids.some(id=>!cardById(id))){notify('Some saved cards are unavailable. Start a new session.');return;}
  if(r.kind==='recall'){quiz=null;session={cards:r.cardIds.map(cardById),index:r.index,revealed:r.revealed,practice:r.practice,ratings:[...r.ratings],course:r.course,draft:r.draft};go('recall',r.course?{course:r.course}:{});}
  else{session=null;quiz={cards:r.items.map(item=>{const c=cardById(item.id);return {...c,options:item.order.map(n=>({text:n===0?c.answer:c.wrong[n-1],correct:n===0}))};}),index:r.index,selected:r.selected,answers:r.answers.map(a=>({...a}))};go('quiz');}
  render();
}

function sourceLink(id,references=[]){if(id==='user')return '<span class="source-link">Your own study material</span>';const refs=[...new Set([id,...references])].map(key=>sources.find(s=>s.id===key)).filter(Boolean);return '<span class="source-link">'+refs.map(s=>esc(s.title)).join(' · ')+'</span>';}
function sourceText(id){const s=sources.find(s=>s.id===id);return s?.title||'Your study notes';}
function selectedPool(params=route().params){return selectStudyCards(allCards(),courses,state.settings,{course:params.get('course')||'',outcome:params.get('outcome')||'',topic:params.get('topic')||''});}
function outcomeOptions(id,params=route().params){if(params.get('course')!=='BIOL1006')return '';return `<select id="${id}" aria-label="Anatomy learning outcome"><option value="">All Anatomy outcomes</option>${anatomyOutcomes.map(o=>`<option value="${o.id}" ${params.get('outcome')===String(o.id)?'selected':''}>Outcome ${o.id} · ${esc(o.title)}</option>`).join('')}</select>`;}
function anatomySummary(){const pdfCards=seedCards.filter(c=>c.pack==='anatomy100-pdf');return `<section class="panel anatomy-pack"><span class="eyebrow">YOUR UPLOADED ANATOMY 100 PDF</span><h2 style="font-family:Georgia;font-weight:400">Six learning outcomes, ready to study.</h2><p class="small muted">${pdfCards.length} new recall cards, ${pdfCards.filter(c=>c.wrong.length===3).length} quiz questions and ${lessons.filter(l=>l.pack==='anatomy100-pdf').length} notes from your 30-page PDF. Page references appear beside each answer. Important clarifications have additional verification links.</p><div class="card-list">${anatomyOutcomes.map(o=>`<article class="course-row"><div><span class="eyebrow">OUTCOME ${o.id} · PDF pp. ${o.pages}</span><h3>${esc(o.title)}</h3><span class="coverage muted">${pdfCards.filter(c=>c.outcome===o.id).length} recall cards</span></div><button data-action="study-outcome" data-mode="recall" data-outcome="${o.id}">Recall</button><button data-action="study-outcome" data-mode="quiz" data-outcome="${o.id}">Quiz</button><button data-action="study-outcome" data-mode="notes" data-outcome="${o.id}">Notes</button></article>`).join('')}</div><p class="small muted">Adapted study notes, not an authenticated official lecture pack. Original diagrams stay in your PDF; practical skills require your taught lab procedures.</p></section><div class="spacer"></div>`;}
function notify(message){clearTimeout(toastTimeout);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimeout=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function save(){if(storageBlocked){$('#save-status').textContent='! Not saved — see Settings';return false;}try{if(localStorage.getItem(KEY)!==lastPersisted){storageBlocked=true;loadError='Another tab has newer saved data. Reload to use it, or export this tab’s data before restoring a backup.';$('#save-status').textContent='! Another tab changed data — reload';notify(loadError);return false;}state.history=state.history.slice(-50000);const next=JSON.stringify(state);localStorage.setItem(KEY,next);lastPersisted=next;$('#save-status').textContent='Saved on this device';cloudAccount.localSaved();return true;}catch{$('#save-status').textContent='! Not saved — export a backup';notify('Device storage is unavailable or full. Export a backup in Settings.');return false;}}
function go(page,params={}){const q=new URLSearchParams(params).toString();location.hash=page+(q?'?'+q:'');}
function route(){const [page='today',query='']=(location.hash.slice(1)||'today').split('?');return {page,params:new URLSearchParams(query)};}
function scopeControls(){return `<div class="scope"><select id="scope-year" aria-label="Study year">${[1,2,3,4].map(y=>`<option value="${y}" ${state.settings.year===y?'selected':''}>Year ${y}</option>`).join('')}</select><select id="scope-semester" aria-label="Study semester">${[1,2].map(s=>`<option value="${s}" ${state.settings.semester===s?'selected':''}>Semester ${s}</option>`).join('')}</select></div>`;}
function heading(title,description='',scope=false){return `<div class="page-heading"><div><span class="eyebrow">ADELAIDE UNIVERSITY · PHYSIOTHERAPY (HONOURS)</span><h1>${title}</h1><p>${description}</p></div>${scope?scopeControls():''}</div>`;}
function courseSelect(id,includeAll=true,value=''){const list=[...new Map(courses.filter(c=>c.year===1||state.notes.some(n=>n.course===c.id)).map(c=>[c.id,c])).values()];return `<select id="${id}" aria-label="Filter by course">${includeAll?'<option value="">All courses with notes</option>':''}${list.map(c=>`<option value="${c.id}" ${value===c.id?'selected':''}>${c.id} · ${esc(c.title)}</option>`).join('')}</select>`;}
function empty(title,body,action=''){return `<div class="empty"><h2>${title}</h2><p>${body}</p>${action}</div>`;}
function renderNav(page){
  const practicePages=['guided','recall','quiz','mistakes','diagrams','practice'],morePages=['outcomes','resources','planner','progress','account','settings'];
  const link=(id,label)=>`<a href="#${id}" class="primary-nav-link ${page===id?'active':''}" ${page===id?'aria-current="page"':''} aria-label="${navItems.find(([key])=>key===id)?.[1]||label}">${label}</a>`;
  const menuLink=([id,label])=>`<a href="#${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(id)}<span>${label}</span></a>`;
  const menu=(label,ids,extra='')=>`<details class="nav-group ${extra} ${ids.includes(page)?'active':''}"><summary>${label}${icon('caret')}</summary><div class="nav-popover">${ids.map(id=>menuLink(navItems.find(([key])=>key===id)||[id,'Settings & backup'])).join('')}</div></details>`;
  $('#nav').innerHTML=link('today','Today')+link('courses','Courses')+menu('Practice',practicePages)+link('notes','Notes')+menu('More',morePages,'menu-more');
}
function courseProgress(id){const pack=allCards().filter(c=>c.course===id);return {total:pack.length,seen:pack.filter(c=>state.schedule[c.id]).length,established:pack.filter(c=>(state.schedule[c.id]?.successes||0)>=3).length};}
function courseCard(c,index=0){const p=courseProgress(c.id),pct=p.total?Math.round(p.seen/p.total*100):0;const title=c.id==='HLTH1016'?'Evidence Based Practice':c.title;return `<article class="catalogue-row"><a class="catalogue-link" href="#courses?course=${c.id}" aria-label="Open ${esc(c.title)}"></a><span class="catalogue-number" aria-hidden="true">${String(index+1).padStart(2,'0')}</span><span class="catalogue-code">${c.id}</span><h3>${esc(title)}</h3><span class="catalogue-count">${p.total?p.total+' recall cards':'Course roadmap'}</span><div class="catalogue-progress"><div class="progress-track" role="progressbar" aria-label="Cards introduced in ${c.id}" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"><i style="width:${pct}%"></i></div><span>${pct}%</span></div>${icon('arrow')}</article>`;}
function timerPanel(){return `<section class="focus-panel" aria-label="Focus session"><h3>Make a little room to focus</h3><p>One thing at a time. A break when you need it.</p><div class="timer" id="timer-display" role="timer" aria-label="Focus time remaining">${clockText(timerRemaining())}</div><div class="timer-actions"><button class="primary" data-action="timer-toggle" id="timer-toggle">${timer.running?'Pause':timer.remaining<timer.duration*60?'Resume':'Start focus'}</button><button data-action="timer-reset" aria-label="Reset focus timer">${icon('reset')}</button><select id="timer-length" aria-label="Focus duration" ${timer.running?'disabled':''}>${[...new Set([timer.duration,5,15,25,45])].sort((a,b)=>a-b).map(m=>`<option value="${m}" ${timer.duration===m?'selected':''}>${m} min</option>`).join('')}</select></div></section>`;}
// The recall panel uses a bundled decorative image rather than a teaching diagram.
function renderToday(){
  const pack=currentCards(),q=reviewQueue(pack,state),due=pack.filter(c=>state.schedule[c.id]?.due<=Date.now()).length,fresh=q.filter(c=>!state.schedule[c.id]).length,today=dayKey(Date.now(),state.settings.timezone);
  const reviewed=state.history.filter(h=>h.type==='recall'&&dayKey(h.at,state.settings.timezone)===today).length,mistakes=Object.values(state.mistakes).filter(m=>!m.resolved&&pack.some(c=>c.id===m.card)).length,introduced=pack.filter(c=>state.schedule[c.id]).length;
  main.innerHTML=`<div class="collection-head"><div><span class="eyebrow">BOSCO’S STUDY DESK</span><h1>Make room for understanding.</h1></div><div class="desk-scope">${scopeControls()}<span class="entry-year" title="Starting university in 2027">2027</span></div></div><div class="collection-session"><section class="hero" aria-labelledby="daily-title"><div class="hero-copy"><span class="hero-label">DAILY RECALL</span><h2 id="daily-title">${q.length?'Your next small step.':'Room to connect the dots.'}</h2><p>${q.length?fresh?fresh+' new '+(fresh===1?'card':'cards')+' ready to explore':due+' '+(due===1?'review':'reviews')+' ready to revisit':'Explore your notes or revisit a course.'}</p><button class="hero-cta" data-action="daily">${q.length?'Start recall':'Explore courses'}${icon('arrow')}</button><span class="hero-due">${due} ${due===1?'review':'reviews'} due</span></div></section><aside class="collection-focus" aria-label="Focus and study activity"><span class="eyebrow">FOCUS SESSION</span>${timerPanel()}<dl class="collection-activity"><div><dt>Reviewed today</dt><dd>${reviewed}</dd></div><div><dt>To revisit</dt><dd>${mistakes}</dd></div><div><dt>Cards introduced</dt><dd>${introduced}</dd></div></dl></aside></div><section class="collection-courses" aria-labelledby="semester-title"><div class="collection-course-heading"><h2 id="semester-title">Your semester</h2><a href="#courses">Course map</a></div><div class="catalogue">${activeCourses().map(courseCard).join('')||'<p class="catalogue-empty">No courses in this selection. Choose another semester or explore the course map.</p>'}</div></section>`;
}
function renderCourses(params){const id=params.get('course');if(id){renderCourse(id);return;}const stream=state.settings.stream;main.innerHTML=heading('Your course, connected.','The four-year pathway, with a detailed starting library for Year 1.')+`<div class="toolbar"><label for="stream-select" style="margin:0">Honours pathway</label><select id="stream-select"><option value="professional" ${stream==='professional'?'selected':''}>Professional stream</option><option value="research" ${stream==='research'?'selected':''}>Research stream</option></select><input id="course-search" aria-label="Search course map" placeholder="Find a course or code…"></div><div id="course-results"></div><div class="notice">2027 study plan checked ${verifiedOn}. Both streams total 192 units over four years. Stream choices change the timing of some final-year courses. Follow your personal study plan for enrolment.${sourceLink('degree')}</div>`;filterCourseMap('');}
function filterCourseMap(query){const list=courses.filter(c=>(c.stream==='both'||c.stream===state.settings.stream)&&matches(c.title+' '+c.id,query));$('#course-results').innerHTML=list.length?[1,2,3,4].map(y=>{const subset=list.filter(c=>c.year===y);return subset.length?`<section class="year-block"><div class="section-title"><h2>Year ${y}</h2><span class="pill">${y===1?'Study packs included':'Course roadmap'}</span></div>${[1,2].map(s=>{const rows=subset.filter(c=>c.semester===s);return rows.length?`<h3 class="semester-title">Semester ${s} · ${rows.reduce((sum,c)=>sum+c.units,0)} units${query?' matching your search':''}</h3><div class="card-list">${rows.map(c=>`<article class="course-row"><div><span class="eyebrow">${c.id} · ${c.units} UNITS</span><h3>${esc(c.title)}</h3><span class="coverage muted">${c.year===1?`${allCards().filter(x=>x.course===c.id).length} cards · ${lessons.filter(x=>x.course===c.id).length} study notes`:'Course map and official link; no seeded study pack yet'}</span></div><span class="pill">${c.area}</span><button data-action="course" data-id="${c.id}">${c.year===1?'Open pack':'View course'}</button></article>`).join('')}</div>`:'';}).join('')}</section>`:'';}).join(''):empty('No matching courses','Try a course code or a shorter phrase.');}
function renderCourse(id){const c=courses.find(x=>x.id===id);if(!c){main.innerHTML=empty('Course not found','Return to the course map.','<a href="#courses">Course map</a>');return;}const pack=allCards().filter(x=>x.course===id);main.innerHTML=heading(esc(c.title),`${c.id} · Year ${c.year} · ${c.units} units`)+`<a class="small" href="#courses">← Back to course map</a><div class="spacer"></div><section class="panel course-detail"><p>${esc(c.summary)}</p>${c.outcomes.length?`<h2 style="font-size:14px">Starting study targets</h2><ul>${c.outcomes.map(o=>`<li>${esc(o)}</li>`).join('')}</ul>`:''}<a href="${esc(c.url)}" target="_blank" rel="noopener noreferrer" class="source-link">Official Adelaide course overview ↗</a><div class="button-row">${pack.length?`<button class="primary" data-action="recall-course" data-id="${c.id}">Recall this course</button><button data-action="quiz-course" data-id="${c.id}">Quiz this course</button>`:''}<button data-action="new-note" data-id="${c.id}">Add personal note</button><button data-action="new-card" data-id="${c.id}">Add recall card</button></div></section><div class="spacer"></div>${id==='BIOL1006'?anatomySummary():''}<div class="two-cols">${lessons.filter(l=>l.course===id).map(lessonCard).join('')}</div>${!pack.length?'<div class="notice">This later-year course is included as a roadmap. You can add your own notes and recall cards; there is no prewritten study pack for it yet.</div>':''}`;}
function recallCourseOptions(id,value=''){return `<select id="${id}" aria-label="Recall course"><option value="">Selected semester</option>${[...new Set(allCards().map(c=>c.course))].map(c=>`<option value="${c}" ${value===c?'selected':''}>${c} · ${esc(courseName(c))}</option>`).join('')}</select>`;}
function renderRecall(params){if(session){renderRecallSession();return;}const course=params.get('course')||'',pool=selectedPool(params),queue=reviewQueue(pool,state),due=pool.filter(c=>state.schedule[c.id]?.due<=Date.now()).length;main.innerHTML=heading('Remember it for longer.','Try to retrieve the answer before you reveal it. Honest ratings make the next review more useful.')+`<div class="toolbar">${recallCourseOptions('recall-course',course)}${outcomeOptions('recall-outcome',params)}${params.get('topic')?`<span class="pill">${esc(params.get('topic'))}</span><a href="#recall?course=${encodeURIComponent(course)}">All course cards</a>`:''}</div><section class="panel"><span class="eyebrow">SPACED RECALL</span><h2 style="font-family:Georgia;font-size:30px;font-weight:400">${queue.length} cards ready for a little attention.</h2><p class="muted small">${due} due reviews + ${queue.length-due} new cards. New cards are limited to ${state.settings.newLimit} per day across all courses.</p><div class="button-row"><button class="primary" data-action="start-recall" ${queue.length?'':'disabled'}>Start recall →</button><button data-action="practice-recall" ${pool.length?'':'disabled'}>Practise any card</button><button data-action="new-card" data-id="${esc(course||activeCourses()[0]?.id||'BIOL1006')}">Create my own card</button></div><p class="small muted">Practice mode lets you browse cards without changing your schedule or statistics.</p></section><div class="study-methods"><section class="panel"><h3>1. Retrieve</h3><p>Say or write your answer before looking. A little effort reveals what you actually remember.</p></section><section class="panel"><h3>2. Check & rate</h3><p>Again = revisit in 10 minutes. Hard, Good and Easy use progressively longer intervals.</p></section><section class="panel"><h3>3. Return later</h3><p>Review when a card is due. Missed days carry no penalty; the cards simply wait.</p></section></div><div class="notice">Spacing and retrieval practice are supported by learning research. This app uses a transparent, simple interval scheduler; its exact timings are a design choice, not a guarantee of retention.${sourceLink('learning')}</div>`;}
function startRecall(practice=false,specificId=null,replace=false){if(state.learning.recall&&!replace){pendingSessionStart=()=>startRecall(practice,specificId,true);openModal('Replace your paused recall session?','<p>Your rated cards stay saved. Starting again replaces the unfinished session and its draft answer.</p><div class="button-row"><button class="primary" data-action="replace-session-start">Start a new session</button><button data-action="close-modal">Keep my session</button></div>');return;}const course=route().params.get('course')||'',pool=specificId?[cardById(specificId)].filter(Boolean):selectedPool();const queue=specificId?pool:practice?interleave(shuffle(pool)).slice(0,20):reviewQueue(pool,state);if(!queue.length){notify('No cards are ready in this selection.');return;}session={cards:queue,index:0,revealed:false,practice,ratings:[],course};render();}
function renderRecallSession(){const s=session;if(s.index>=s.cards.length){const practice=s.practice;main.innerHTML=heading('A little stronger than before.','You made time to retrieve, check and learn.')+empty('Session complete',practice?`You practised ${s.cards.length} cards. Your review schedule was left unchanged.`:`${s.ratings.length} cards rated. Cards marked Again will return in 10 minutes.`, '<button class="primary" data-action="end-recall">Back to recall</button>');return;}const c=s.cards[s.index];main.innerHTML=heading(s.practice?'A little extra practice.':'One idea at a time.','Aim for understanding. You do not need perfect wording.')+`<section class="recall-shell"><div class="session-meta"><span>${s.index+1} / ${s.cards.length} ${s.practice?'· Practice mode':''}</span><button class="text-button" data-action="end-recall">Pause session</button></div><div class="progress-track"><i style="width:${s.index/s.cards.length*100}%"></i></div><div class="spacer"></div><article class="flashcard"><span class="pill">${esc(c.course)} · ${esc(c.topic)}</span><h2>${esc(c.question)}</h2>${s.revealed?`<div class="answer">${esc(c.answer)}</div>${sourceLink(c.source,c.references)}${learningTools.helpForCard(c)}`:`<label for="recall-draft" class="small muted">Optional: put your answer into words (saved with this session)</label><textarea id="recall-draft" maxlength="20000" placeholder="What do you remember?" aria-label="Your recall answer">${esc(s.draft||'')}</textarea><div class="button-row"><button class="primary" data-action="reveal">Reveal answer</button></div>`}</article>${s.revealed?s.practice?'<div class="button-row"><button class="primary" data-action="practice-next">Next card →</button></div>':`<p class="small muted">How well did you retrieve it before revealing?</p><div class="ratings">${['again','hard','good','easy'].map(g=>`<button class="rating-${g}" data-action="rate" data-grade="${g}">${g[0].toUpperCase()+g.slice(1)}<small>${g==='again'?'10 minutes':(()=>{const days=scheduleCard(state.schedule[c.id],g).interval;return days+' '+(days===1?'day':'days');})()}</small></button>`).join('')}</div>`:''}</section>`;}
function rateCard(grade){if(!session?.revealed||session.index>=session.cards.length)return;const c=session.cards[session.index],now=Date.now(),isNew=!state.schedule[c.id];state.schedule[c.id]=scheduleCard(state.schedule[c.id],grade,now);state.history.push({type:'recall',at:now,card:c.id,grade,new:isNew});if(grade==='again')recordMistake(state,c,'Could not retrieve during spaced recall',now);else if(grade==='good'||grade==='easy'){if(state.mistakes[c.id])state.mistakes[c.id].resolved=true;}session.ratings.push(grade);session.index++;session.revealed=false;session.draft='';persistActive(false);save();render();}
function renderQuiz(params){if(quiz){renderQuizSession();return;}const course=params.get('course')||'';const pool=selectedPool(params).filter(c=>c.wrong.length===3);main.innerHTML=heading('Check your understanding.','Short quizzes, clear explanations and a useful next step for every mistake.')+`<div class="toolbar">${recallCourseOptions('quiz-course',course)}${outcomeOptions('quiz-outcome',params)}<select id="quiz-length" aria-label="Quiz length"><option value="5">5 questions</option><option value="10" selected>10 questions</option><option value="20">20 questions</option></select></div><section class="panel"><span class="eyebrow">LOW-PRESSURE PRACTICE</span><h2 style="font-family:Georgia;font-size:29px;font-weight:400">Learn from the answer, not just the score.</h2><p class="small muted">${pool.length} multiple-choice questions available in this selection. Questions and answer positions are shuffled.</p><div class="button-row"><button class="primary" data-action="start-quiz" ${pool.length?'':'disabled'}>Start quick quiz →</button><button data-action="quiz-mistakes">Retest my mistakes</button></div><p class="small muted">Quiz answers update your mistake log. Your spaced recall schedule changes only when you rate a recall card.</p></section><div class="notice">Original supplementary questions based on public course topics and your uploaded Anatomy 100 study notes. These are not Adelaide examination questions. A short quiz score does not establish practical competence.</div>`;}
function startQuiz(mistakesOnly=false,specificId=null,replace=false){if(state.learning.quiz&&!replace){pendingSessionStart=()=>startQuiz(mistakesOnly,specificId,true);openModal('Replace your paused quiz?','<p>Your recorded attempts stay saved. Starting again replaces the unfinished quiz.</p><div class="button-row"><button class="primary" data-action="replace-session-start">Start a new session</button><button data-action="close-modal">Keep my session</button></div>');return;}const course=route().params.get('course')||'';let pool=specificId?[cardById(specificId)].filter(Boolean):selectedPool();pool=pool.filter(c=>c.wrong.length===3&&(!mistakesOnly||state.mistakes[c.id]&&!state.mistakes[c.id].resolved));if(!pool.length){notify('No multiple-choice questions in this selection. Use recall to retest open-answer cards.');return;}const length=Number($('#quiz-length')?.value||10);quiz={cards:interleave(shuffle(pool)).slice(0,specificId?1:length).map(c=>({...c,options:shuffle([{text:c.answer,correct:true},...c.wrong.map(text=>({text,correct:false}))])})),index:0,answers:[],selected:null};const selection=specificId?{course:pool[0].course}:Object.fromEntries(route().params);go('quiz',selection);render();}
function renderQuizSession(){const q=quiz;if(q.index>=q.cards.length){const correct=q.answers.filter(x=>x.correct).length;main.innerHTML=heading('A useful check-in.','Take the explanation with you, then revisit it later.')+`<section class="panel"><span class="eyebrow">QUIZ COMPLETE</span><h2 style="font-family:Georgia;font-size:36px;font-weight:400">${correct} / ${q.cards.length}</h2><p class="small muted">${q.cards.length-correct} ${q.cards.length-correct===1?'idea':'ideas'} to revisit. Every missed answer is saved in your mistake log.</p><div class="button-row"><button class="primary" data-action="finish-quiz">Back to quizzes</button><button data-action="open-mistakes">Review mistakes</button></div></section><div class="spacer"></div><div class="card-list">${q.answers.map((a,i)=>`<article class="panel"><span class="pill ${a.correct?'':'orange'}">${a.correct?'Correct':'Revisit'}</span><h3>${esc(q.cards[i].question)}</h3><p>${esc(q.cards[i].answer)}</p>${sourceLink(q.cards[i].source,q.cards[i].references)}</article>`).join('')}</div>`;return;}const c=q.cards[q.index];main.innerHTML=heading('Make your thinking visible.','Choose an answer, then read the explanation.')+`<section class="recall-shell"><div class="session-meta"><span>Question ${q.index+1} / ${q.cards.length}</span><button class="text-button" data-action="end-quiz">Pause quiz</button></div><article class="flashcard"><span class="pill">${esc(c.course)} · ${esc(c.topic)}</span><h2>${esc(c.question)}</h2>${c.options.map((o,i)=>`<button class="choice ${q.selected!==null?(o.correct?'correct':q.selected===i?'wrong':''):''}" data-action="answer-quiz" data-index="${i}" ${q.selected!==null?'disabled':''}><span>${String.fromCharCode(65+i)}</span>${esc(o.text)}</button>`).join('')}${q.selected!==null?`<div class="feedback ${c.options[q.selected].correct?'':'incorrect'}"><strong>${c.options[q.selected].correct?'That’s right.':'A useful one to revisit.'}</strong><p>${esc(c.answer)}</p><p class="small">${c.options[q.selected].correct?'Keep connecting the explanation to the question.':'Saved to your mistake log. Explain why the correct answer fits before moving on.'}</p>${sourceLink(c.source,c.references)}${learningTools.helpForCard(c)}</div><div class="button-row"><button class="primary" data-action="next-question">${q.index===q.cards.length-1?'See results':'Next question'} →</button></div>`:''}</article></section>`;}
function answerQuiz(index){if(!quiz||quiz.selected!==null)return;const c=quiz.cards[quiz.index],o=c.options[index];if(!o)return;quiz.selected=index;quiz.answers.push({correct:o.correct,selected:index});state.history.push({type:'quiz',at:Date.now(),card:c.id,correct:o.correct});if(!o.correct)recordMistake(state,c,'Quiz choice: '+o.text);else if(state.mistakes[c.id])state.mistakes[c.id].resolved=true;persistActive(false);save();render();}
function renderMistakes(){const open=Object.values(state.mistakes).filter(m=>!m.resolved&&cardById(m.card)).sort((a,b)=>b.last-a.last);main.innerHTML=heading('Your mistakes are a map.','Find the gap, explain the correction, then retrieve it again.')+`<div class="toolbar"><span class="pill orange">${open.length} open ${open.length===1?'mistake':'mistakes'}</span><span class="small muted">${Object.values(state.mistakes).filter(m=>m.resolved).length} corrected through retesting</span></div>${open.length?`<div class="card-list">${open.map(m=>{const c=cardById(m.card);return `<article class="mistake-card"><span class="pill">${esc(c.course)} · ${esc(c.topic)}</span><h3>${esc(c.question)}</h3><details><summary class="small">Review the explanation</summary><p>${esc(c.answer)}</p>${sourceLink(c.source,c.references)}${learningTools.helpForCard(c)}</details><p class="small muted">${esc(m.reason)} · Missed ${m.count} ${m.count===1?'time':'times'}</p><label for="reflection-${c.id}">What confused me, and what will I remember next time?</label><textarea id="reflection-${c.id}" data-reflection="${c.id}" maxlength="20000" placeholder="My correction, in my own words…">${esc(m.reflection)}</textarea><span class="note-status">Reflections save as you type.</span><div class="button-row"><button class="primary" data-action="retest-mistake" data-id="${c.id}">Retest this idea →</button></div></article>`;}).join('')}</div>`:empty('A clear page, for now.','Missed quiz answers and recall cards rated Again appear here.','<a class="primary-link" href="#quiz">Try a quick quiz →</a>')}`;}
function lessonCard(l){const stats=noteStats(l.chapter);return `<article class="lesson-card note-preview"><span class="pill">${l.course}${l.outcome?' · Outcome '+l.outcome:''}</span><h2>${esc(l.title)}</h2><p>${esc(l.body)}</p><div class="note-meta">${stats.minutes} min read · ${stats.checks} recall checks · Worked example</div><div class="button-row"><a class="read-lesson" href="#notes?course=${encodeURIComponent(l.course)}&lesson=${encodeURIComponent(l.id)}">Read full lesson →</a><button data-action="guide-lesson" data-id="${l.id}">Study this idea</button></div></article>`;}
function lessonReader(l){const siblings=lessons.filter(n=>n.course===l.course),i=siblings.findIndex(n=>n.id===l.id),stats=noteStats(l.chapter);const noteUrl=n=>'#notes?course='+encodeURIComponent(n.course)+'&lesson='+encodeURIComponent(n.id);return `<article class="note-reader"><header class="note-reader-header"><a href="#notes?course=${encodeURIComponent(l.course)}">← All ${esc(l.course)} notes</a><p class="note-reading-meta">${stats.minutes} min read · ${stats.words.toLocaleString()} words · ${stats.checks} recall checks${l.outcome?' · Anatomy outcome '+l.outcome:''}</p><p>${esc(l.body)}</p><div class="button-row"><button class="primary" data-action="guide-lesson" data-id="${l.id}">Practise this lesson</button><button data-action="note-from-lesson" data-id="${l.id}">Make it my own</button></div><div class="note-reading-actions"><button data-action="note-answers" data-open="true">Reveal all model answers</button><button data-action="note-answers" data-open="false">Hide all model answers</button></div></header><div class="note-reader-layout">${renderChapter(l.chapter,{prefix:l.id,contents:true,lessonId:l.id})}</div>${noteAttribution(l,sources)}<nav class="note-navigation" aria-label="Other lessons">${i>0?`<a href="${noteUrl(siblings[i-1])}">← ${esc(siblings[i-1].title)}</a>`:'<span></span>'}${i<siblings.length-1?`<a href="${noteUrl(siblings[i+1])}">${esc(siblings[i+1].title)} →</a>`:''}</nav></article>`;}
function renderNotes(){const selected=noteTab==='library'?lessons.find(l=>l.id===route().params.get('lesson')):null;main.innerHTML=heading(selected?esc(selected.title):'Understand it. Put it into words.',selected?esc(selected.course)+' · A complete lesson with explanations, worked examples and model answers.':'Self-contained lessons. Read, explain from memory and check your answers without leaving your desk.')+`<div class="tabs"><button data-action="notes-tab" data-tab="library" class="${noteTab==='library'?'selected':''}">Study library · ${lessons.length}</button><button data-action="notes-tab" data-tab="personal" class="${noteTab==='personal'?'selected':''}">My notes · ${state.notes.length}</button></div>${selected?'<details class="reader-library-tools"><summary>Browse & search notes</summary>':''}<div class="toolbar"><input id="notes-search" aria-label="Search notes" placeholder="Search any concept inside the lessons…">${courseSelect('notes-course',true,route().params.get('course')||'')}${noteTab==='library'?outcomeOptions('notes-outcome'):''}<button class="primary" data-action="new-note">+ Write a note</button><button data-action="print">Print</button></div>${selected?'</details>':''}<p class="print-note">Physio Study Desk · Sources reviewed ${verifiedOn}</p><div id="notes-results"></div>`;filterNotes();}
function filterNotes(){const q=$('#notes-search').value,course=$('#notes-course').value,outcome=noteTab==='library'?($('#notes-outcome')?.value||''):'',focused=noteTab==='library'?lessons.find(l=>l.id===route().params.get('lesson')):null,selected=focused&&!q.trim()&&(!outcome||String(focused.outcome)===outcome)?focused.id:null;main.querySelector('.page-heading h1').textContent=selected?focused.title:'Understand it. Put it into words.';main.querySelector('.page-heading p').textContent=selected?focused.course+' · A complete lesson with explanations, worked examples and model answers.':'Self-contained lessons. Read, explain from memory and check your answers without leaving your desk.';const list=(noteTab==='library'?lessons:state.notes).filter(n=>(!course||n.course===course)&&(!outcome||String(n.outcome)===outcome)&&(!selected||n.id===selected)&&matches(n.title+' '+(n.body||'')+' '+(n.chapter||'')+' '+(n.cue||'')+' '+(n.summary||'')+' '+n.course,q));if(selected&&list.length===1){$('#notes-results').innerHTML=lessonReader(list[0]);return;}$('#notes-results').innerHTML=list.length?`<p class="search-count">${list.length} ${noteTab==='library'?(list.length===1?'in-app lesson':'in-app lessons'):(list.length===1?'personal note':'personal notes')} · ${noteTab==='library'?'Explanations, comparison tables, worked examples and hidden-answer checks.':'Saved only in this browser unless you export a backup.'}</p><div class="two-cols">${list.map(n=>noteTab==='library'?lessonCard(n):`<article class="lesson-card personal-note"><span class="pill">${esc(n.course)}</span><h2>${esc(n.title)}</h2>${n.cue?`<strong class="small">Recall cue</strong><p>${esc(n.cue)}</p>`:''}<p>${esc(n.body)}</p>${n.summary?`<div class="practice-prompt"><strong>My summary</strong>${esc(n.summary)}</div>`:''}<div class="button-row"><button data-action="edit-note" data-id="${esc(n.id)}">Edit note</button><button data-action="card-from-note" data-id="${esc(n.id)}">Make a recall card</button>${allCards().some(c=>c.course===n.course&&c.topic===n.title)?`<a href="#recall?course=${encodeURIComponent(n.course)}&topic=${encodeURIComponent(n.title)}">Recall this note’s cards</a>`:''}</div></article>`).join('')}</div>`:empty('Room for your own understanding.','Add a note, or try another search.');}

function openModal(title,body){modal.innerHTML=`<button class="dialog-close" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button><h2 id="modal-title">${title}</h2>${body}`;modal.showModal();}
function noteForm(note={},lesson=null,course=null){const n=note;openModal(n.id?'Edit your note':'Make the idea your own',`<form id="note-form" data-id="${esc(n.id||'')}"><div class="form-grid"><div><label for="note-course">Course</label>${personalCourseSelect('note-course',n.course||lesson?.course||course||activeCourses()[0]?.id||'BIOL1006')}</div><div><label for="note-title">Title</label><input id="note-title" maxlength="200" required value="${esc(n.title||lesson?.title||'')}"></div><div class="field-wide"><label for="note-cue">Recall cue · the question I should answer</label><input id="note-cue" maxlength="20000" value="${esc(n.cue||'')}"></div><div class="field-wide"><label for="note-body">My explanation</label><textarea id="note-body" maxlength="20000" required>${esc(n.body||(lesson?lessonPlainText(lesson,sources):''))}</textarea></div><div class="field-wide"><label for="note-summary">One-sentence takeaway</label><textarea id="note-summary" style="min-height:70px" maxlength="20000">${esc(n.summary||'')}</textarea></div></div><p class="small muted">Use your own learning notes and fictional examples. Do not enter patient information.</p><div class="button-row"><button class="primary" type="submit">Save note</button><button type="button" data-action="close-modal">Cancel</button></div></form>`);}
function personalCourseSelect(id,value){return `<select id="${id}" aria-label="Course">${[...new Map(courses.map(c=>[c.id,c])).values()].map(c=>`<option value="${c.id}" ${value===c.id?'selected':''}>${c.id} · ${esc(c.title)}</option>`).join('')}</select>`;}
function cardForm(note=null,course=null){openModal('Create a recall card',`<form id="card-form"><label for="custom-course">Course</label>${personalCourseSelect('custom-course',note?.course||course||activeCourses()[0]?.id||'BIOL1006')}<label for="custom-topic">Topic</label><input id="custom-topic" maxlength="200" required value="${esc(note?.title||'My lecture notes')}"><label for="custom-question">One clear question</label><textarea id="custom-question" maxlength="4000" required style="min-height:70px">${esc(note?.cue||'')}</textarea><label for="custom-answer">A focused answer</label><textarea id="custom-answer" maxlength="10000" required>${esc(note?.summary||'')}</textarea><p class="small muted">Small, specific prompts work best. Your card joins the spaced recall queue for this course.</p><div class="button-row"><button class="primary" type="submit">Add to recall</button><button type="button" data-action="close-modal">Cancel</button></div></form>`);}
function renderResources(){main.innerHTML=heading('Follow the evidence.','Official course information, open learning resources and the research behind your study tools.')+`<div class="toolbar"><input id="resource-search" aria-label="Search resources" placeholder="Search anatomy, evidence, culture…"><select id="resource-type" aria-label="Source category"><option value="">All source types</option>${[...new Set(sources.map(s=>s.type))].map(t=>`<option>${t}</option>`).join('')}</select></div><div class="notice" style="margin:0 0 22px"><b>Research scope · ${verifiedOn}.</b> The degree structure was verified with the 2027 selector in Adelaide’s live page. Public Year 1 course descriptions guide the topic mapping. Your uploaded Anatomy 100 PDF is now mapped to six learning outcomes with page references. OpenStax, PEDro, Ahpra, WHO and community-led resources support the supplementary material. Later years have a roadmap only. Your lecture content, reading lists and assessment rubrics still need to come from your enrolled course. External readings need an internet connection.</div><div class="two-cols" id="resource-results"></div>`;filterResources();}
function filterResources(){const q=$('#resource-search').value,t=$('#resource-type').value;const list=sources.filter(s=>(!t||s.type===t)&&matches(s.title+' '+s.description,q));$('#resource-results').innerHTML=list.map(s=>`<article class="resource"><span class="pill">${s.type}</span><br>${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>`:`<strong>${esc(s.title)}</strong>`}<p>${esc(s.description)}</p><div class="resource-domain">${s.url?new URL(s.url).hostname:esc(s.filename)+' · local source, not uploaded'}</div></article>`).join('')||empty('No matching resources','Try a broader topic or source category.');}
function renderPractice(){const station=stations.find(s=>s.id===stationId);main.innerHTML=heading('Think it through. Say it aloud.','Timed reasoning and communication practice to support your supervised classes.')+`<p class="small muted">These self-checks are original preparation exercises, not official OSCE rubrics or assessments of clinical competence.</p><div class="spacer"></div>${station?`<a href="#practice" class="small" data-action="back-stations">← All practice stations</a><div class="spacer"></div><section class="panel"><span class="pill">${station.course} · suggested ${station.minutes} minutes</span><h2 style="font-family:Georgia;font-weight:400">${station.title}</h2><p>${station.brief}</p>${sourceLink(station.source)}<form id="station-form" data-id="${station.id}"><ul class="checklist">${station.checks.map((c,i)=>`<li><label><input type="checkbox" name="station-check" value="${i}">${c}</label></li>`).join('')}</ul><label for="station-reflection">One thing I would improve next time</label><textarea id="station-reflection" maxlength="20000" placeholder="${esc(station.debrief)}"></textarea><div class="button-row"><button type="submit" class="primary">Save my reflection</button></div></form></section><div class="spacer"></div>${timerPanel()}`:`<div class="card-list">${stations.map(s=>`<article class="course-row"><div><span class="eyebrow">${s.course} · ${s.minutes} MINUTES</span><h3>${s.title}</h3><p>${s.brief}</p></div><button class="primary" data-action="open-station" data-id="${s.id}">Open station →</button></article>`).join('')}</div><div class="notice">Physical examination, manual handling and treatment techniques require your university’s instruction, feedback and supervision. These stations focus on discussion and reasoning using fictional cases.</div>`}`;}
function renderPlanner(){const tasks=[...state.tasks].sort((a,b)=>a.date.localeCompare(b.date));main.innerHTML=heading('Make space for the important things.','A small, realistic plan beats a perfect one you cannot keep.')+`<div class="two-cols"><section class="panel"><h2 style="font-size:16px">Add a study task</h2><form id="task-form"><label for="task-title">What will you do?</label><input id="task-title" maxlength="200" required placeholder="Explain the cardiac cycle from memory"><label for="task-course">Course</label>${personalCourseSelect('task-course',activeCourses()[0]?.id||'BIOL1006')}<label for="task-date">Planned date</label><input id="task-date" type="date" value="${dayKey(Date.now(),state.settings.timezone)}" required><div class="button-row"><button class="primary" type="submit">Add task</button></div></form></section><section class="panel"><h2 style="font-size:16px">A repeatable weekly rhythm</h2><p class="small">Before class: preview the learning outcomes and write two questions.</p><p class="small">After class: explain the main idea without looking; make a few focused cards.</p><p class="small">During the week: revisit due cards, mix subjects and correct one recurring mistake.</p><p class="small">Before a practical: rehearse your explanation and bring uncertainties to your tutor.</p><p class="small muted">This is a suggested study routine. Your actual assignment dates are not preloaded.</p></section></div><div class="spacer"></div><section class="panel"><div class="section-title"><h2>Your plan</h2><span class="small muted">${tasks.filter(t=>t.done).length} / ${tasks.length} completed</span></div>${tasks.length?tasks.map(t=>`<div class="task ${t.done?'done':''}"><input type="checkbox" data-task="${esc(t.id)}" aria-label="Complete ${esc(t.title)}" ${t.done?'checked':''}><div><strong>${esc(t.title)}</strong><small>${esc(t.course)} · ${formatDate(t.date+'T12:00:00')}</small></div><button data-action="remove-task" data-id="${esc(t.id)}">Remove</button></div>`).join(''):'<p class="small muted">No tasks yet. Start with one manageable study session.</p>'}</section>`;}
function formatDate(value){return new Intl.DateTimeFormat('en-AU',{day:'numeric',month:'short'}).format(new Date(value));}
function renderProgress(){const now=Date.now(),q=state.history.filter(h=>h.type==='quiz'),right=q.filter(h=>h.correct).length,recalls=state.history.filter(h=>h.type==='recall');const days=Array.from({length:7},(_,i)=>{const at=now-(6-i)*DAY,key=dayKey(at,state.settings.timezone);return {at,key,count:state.history.filter(h=>h.type!=='focus'&&dayKey(h.at,state.settings.timezone)===key).length};});const max=Math.max(1,...days.map(d=>d.count));main.innerHTML=heading('See the work you’re putting in.','Useful signals to guide your next session. No streaks to protect.')+`<div class="stats"><div class="stat"><div class="stat-top">Recall attempts</div><strong>${recalls.length}</strong><small>All courses, all time</small></div><div class="stat"><div class="stat-top">Quiz accuracy</div><strong>${q.length?Math.round(right/q.length*100)+'%':'—'}</strong><small>${right} correct / ${q.length} attempts</small></div><div class="stat"><div class="stat-top">Focus minutes</div><strong>${Math.round(state.history.filter(h=>h.type==='focus').reduce((a,h)=>a+h.minutes,0))}</strong><small>Completed timers only</small></div><div class="stat"><div class="stat-top">Practical reflections</div><strong>${state.stationLogs.length}</strong><small>Self-assessment, not certification</small></div></div><div class="two-cols"><section class="panel"><h2 style="font-size:14px">Retrieval practice · last 7 days</h2><div class="chart" role="img" aria-label="Daily retrieval attempts: ${days.map(d=>d.key+': '+d.count).join(', ')}">${days.map(d=>`<div class="chart-col"><b>${d.count}</b><div class="chart-bar" style="height:${Math.max(2,d.count/max*100)}px"></div><span>${formatDate(d.at)}</span></div>`).join('')}</div><p class="small muted">Recall ratings + quiz answers · ${state.settings.timezone==='local'?'device timezone':'Adelaide time'}</p></section><section class="panel"><h2 style="font-size:14px">What these numbers mean</h2><p class="small muted">“Introduced” means a card has been rated at least once. “Established” means three successful recall ratings since its last Again. Neither is a validated measure of mastery.</p><p class="small muted">Quiz accuracy includes repeat attempts. Use it to notice gaps, then practise explaining the ideas and applying them in class.</p></section></div><div class="spacer"></div><section class="panel table-wrap"><table><thead><tr><th>COURSE</th><th>INTRODUCED</th><th>ESTABLISHED</th><th>OPEN MISTAKES</th></tr></thead><tbody>${[...new Set(allCards().map(c=>c.course))].map(id=>{const p=courseProgress(id);return `<tr><td>${esc(id)}</td><td>${p.seen} / ${p.total}</td><td>${p.established}</td><td>${Object.values(state.mistakes).filter(m=>m.course===id&&!m.resolved).length}</td></tr>`;}).join('')}</tbody></table></section>${state.stationLogs.length?`<div class="spacer"></div><section class="panel"><h2 style="font-size:14px">Recent practical reflections</h2>${state.stationLogs.slice(-5).reverse().map(l=>`<p class="small"><b>${esc(stations.find(s=>s.id===l.station)?.title||l.station)}</b> · ${l.checked}/${l.total} self-checks · ${formatDate(l.at)}<br>${esc(l.reflection||'No written reflection')}</p>`).join('')}</section>`:''}`;}
function renderSettings(){main.innerHTML=heading('Your desk, your pace.','Choose your study focus and keep a portable copy of your learning.')+`<div class="two-cols"><section class="panel"><h2 style="font-size:16px">Study settings</h2><form id="settings-form"><label for="settings-year">Current year</label><select id="settings-year">${[1,2,3,4].map(y=>`<option value="${y}" ${state.settings.year===y?'selected':''}>Year ${y}</option>`).join('')}</select><label for="settings-semester">Current semester</label><select id="settings-semester">${[1,2].map(s=>`<option value="${s}" ${state.settings.semester===s?'selected':''}>Semester ${s}</option>`).join('')}</select><label for="settings-stream">Honours pathway (roadmap)</label><select id="settings-stream"><option value="professional" ${state.settings.stream==='professional'?'selected':''}>Professional stream</option><option value="research" ${state.settings.stream==='research'?'selected':''}>Research stream</option></select><label for="settings-limit">New cards per day (1–50)</label><input id="settings-limit" type="number" min="1" max="50" value="${state.settings.newLimit}" required><label for="settings-timezone">Daily study boundary</label><select id="settings-timezone"><option value="Australia/Adelaide" ${state.settings.timezone==='Australia/Adelaide'?'selected':''}>Adelaide time</option><option value="local" ${state.settings.timezone==='local'?'selected':''}>Device timezone</option></select><div class="button-row"><button class="primary" type="submit">Save settings</button></div></form></section><section class="panel"><h2 style="font-size:16px">Keep your learning with you</h2><p class="small">Notes, cards, schedules, mistakes and tasks save in this browser. Connect Google to save the same study records across devices, or use a backup to transfer them manually.</p><p class="small">Export a backup regularly, especially before clearing browser data or moving devices. On another device, open the same app and import that file.</p><div class="button-row"><a class="primary-link" href="#account">Account &amp; sync</a><button class="primary" data-action="export">Export backup</button><button data-action="import">Import backup</button></div><input id="import-file" type="file" accept="application/json,.json" hidden>${storageBlocked?`<div class="notice"><b>Saved data needs attention.</b> ${esc(loadError||'Device storage is unavailable.')}<div class="button-row"><button data-action="export-raw">Export stored data</button></div></div>`:''}<div class="spacer"></div><h3 style="font-size:13px">Offline study</h3><p class="small">Once loaded on HTTPS, the app caches its own notes, quizzes and screens for offline use. External source pages still need internet. First visit each device while online.</p><span class="small muted" id="offline-status">Checking offline support…</span><div class="spacer"></div><a href="#resources">Research & source library ↗</a></section></div><div class="notice"><b>How the scheduler works.</b> Again returns a card in 10 minutes. First Hard or Good schedules one day; first Easy schedules four days. Later successful ratings multiply the previous interval (Hard ×1.2, Good ×2.5, Easy ×3.3), with minimum increases and a 365-day cap. Quiz answers do not reschedule cards. This is a simple custom scheduler, not Anki/FSRS.</div><div class="notice"><b>Coverage.</b> ${seedCards.length} original recall cards (${seedCards.filter(c=>c.wrong.length===3).length} also available as multiple-choice questions), ${lessons.length} full in-app lessons, ${stations.length} discussion stations and ${sources.length} linked sources. The Year 1 library is selective, not a complete syllabus. Anatomy 100 also includes your uploaded PDF’s six outcomes, with clarifications checked against additional sources. The original PDF and illustrations are not bundled into the public app.</div>`;offlineStatus();}
function download(text,name){const blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportBackup(){download(JSON.stringify(state,null,2),`physio-study-backup-${dayKey(Date.now(),state.settings.timezone)}.json`);notify('Backup exported. Store it somewhere you can find later.');}
async function importFile(file){if(!file)return;if(file.size>10000000){notify('Choose a Study Desk JSON backup smaller than 10 MB.');return;}try{const candidate=validateBackup(JSON.parse(await file.text()));const known=new Set(courses.map(c=>c.id));if([...candidate.notes,...candidate.customCards,...candidate.tasks].some(x=>!known.has(x.course)))throw new Error('Backup contains an unknown course.');importCandidate=candidate;openModal('Restore this backup?',`<p>This will replace the learning data currently on this device.</p><ul><li>${candidate.notes.length} personal notes</li><li>${candidate.customCards.length} custom cards</li><li>${Object.keys(candidate.schedule).length} review schedules</li><li>${candidate.history.length} study events</li><li>${candidate.tasks.length} study tasks</li></ul><p class="small muted">Export your current data first if you want to keep both versions.</p><div class="button-row"><button data-action="export">Export current data</button><button class="primary" data-action="confirm-import">Replace with this backup</button><button data-action="close-modal">Cancel</button></div>`);}catch(e){notify('Backup not imported: '+e.message);}}
const timer={duration:25,remaining:1500,running:false,deadline:0};
function timerRemaining(){return timer.running?Math.max(0,Math.ceil((timer.deadline-Date.now())/1000)):timer.remaining;}
function clockText(seconds){return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}
function tick(){const remaining=timerRemaining();const el=$('#timer-display');if(el)el.textContent=clockText(remaining);if(timer.running&&remaining===0){timer.running=false;timer.remaining=0;state.history.push({type:'focus',at:Date.now(),minutes:timer.duration});save();notify('Focus session complete. Take a breath and a break.');if($('#timer-toggle'))$('#timer-toggle').textContent='Start again';if($('#timer-length'))$('#timer-length').disabled=false;}}
setInterval(tick,500);
function toggleTimer(){if(timer.running){timer.remaining=timerRemaining();timer.running=false;}else{if(timer.remaining<=0)timer.remaining=timer.duration*60;timer.deadline=Date.now()+timer.remaining*1000;timer.running=true;}if($('#timer-toggle'))$('#timer-toggle').textContent=timer.running?'Pause':'Resume';if($('#timer-length'))$('#timer-length').disabled=timer.running;}
function resetTimer(){timer.running=false;timer.remaining=timer.duration*60;tick();if($('#timer-toggle'))$('#timer-toggle').textContent='Start focus';if($('#timer-length'))$('#timer-length').disabled=false;}
function render(){const changed=persistActive(false);const {page,params}=route();main.dataset.page=page;renderNav(page);if(page!=='recall')session=null;if(page!=='quiz')quiz=null;const renderer={guided:()=>learningTools.renderGuide(params),outcomes:learningTools.renderOutcomes,diagrams:learningTools.renderDiagrams,today:renderToday,courses:()=>renderCourses(params),recall:()=>renderRecall(params),quiz:()=>renderQuiz(params),mistakes:renderMistakes,notes:renderNotes,resources:renderResources,practice:renderPractice,planner:renderPlanner,progress:renderProgress,settings:renderSettings,account:()=>cloudAccount.render(main),privacy:renderPrivacy};(renderer[page]||renderToday)();learningTools.afterRender(page);const sessionChanged=persistActive(false);if(changed||sessionChanged)save();if(storageBlocked)$('#save-status').textContent='! Saved data needs attention';tick();}
window.addEventListener('hashchange',()=>{if(route().page==='notes'&&(route().params.has('outcome')||route().params.has('lesson')))noteTab='library';render();main.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;
  if(a==='replace-session-start'){const start=pendingSessionStart;pendingSessionStart=null;modal.close();start?.();}
  if(a==='note-section'){const section=document.getElementById(b.dataset.section);section?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});section?.focus({preventScroll:true});}
  if(a==='note-answers')for(const check of main.querySelectorAll('.note-check'))check.open=b.dataset.open==='true';
  if(a==='settings')go('settings');
  if(a==='study-outcome'){noteTab='library';go(b.dataset.mode,{course:'BIOL1006',outcome:b.dataset.outcome});}
  if(a==='daily'){if(state.learning.recall){resumeSession('recall');return;}if(reviewQueue(currentCards(),state).length){go('recall');startRecall();}else go('courses');}
  if(a==='course')go('courses',{course:id});
  if(a==='recall-course')go('recall',{course:id});
  if(a==='quiz-course')go('quiz',{course:id});
  if(a==='start-recall')startRecall();
  if(a==='practice-recall')startRecall(true);
  if(a==='reveal'&&session){session.revealed=true;render();}
  if(a==='rate')rateCard(b.dataset.grade);
  if(a==='practice-next'&&session){session.index++;session.revealed=false;session.draft='';render();}
  if(a==='end-recall'){session=null;render();}
  if(a==='start-quiz')startQuiz();
  if(a==='quiz-mistakes')startQuiz(true);
  if(a==='answer-quiz')answerQuiz(Number(b.dataset.index));
  if(a==='next-question'&&quiz&&quiz.selected!==null){quiz.index++;quiz.selected=null;render();}
  if(a==='end-quiz'||a==='finish-quiz'){quiz=null;render();}
  if(a==='open-mistakes'){quiz=null;go('mistakes');}
  if(a==='retest-mistake'){const c=cardById(id);if(c.wrong.length===3){startQuiz(false,id);}else{go('recall');startRecall(false,id);}}
  if(a==='notes-tab'){noteTab=b.dataset.tab;if(route().params.has('lesson'))go('notes',{course:route().params.get('course')||''});render();}
  if(a==='new-note')noteForm({},null,id);
  if(a==='edit-note')noteForm(state.notes.find(n=>n.id===id));
  if(a==='note-from-lesson')noteForm({},lessons.find(l=>l.id===id));
  if(a==='new-card')cardForm(null,id);
  if(a==='card-from-note')cardForm(state.notes.find(n=>n.id===id));
  if(a==='close-modal'){pendingSessionStart=null;modal.close();importCandidate=null;}
  if(a==='print')window.print();
  if(a==='timer-toggle')toggleTimer();
  if(a==='timer-reset')resetTimer();
  if(a==='open-station'){stationId=id;timer.duration=stations.find(s=>s.id===id).minutes;resetTimer();render();}
  if(a==='back-stations'){e.preventDefault();stationId=null;render();}
  if(a==='remove-task'){state.tasks=state.tasks.filter(t=>t.id!==id);save();render();}
  if(a==='export')exportBackup();
  if(a==='import')$('#import-file').click();
  if(a==='confirm-import'&&importCandidate){state=importCandidate;importCandidate=null;storageBlocked=false;loadError='';session=null;quiz=null;try{lastPersisted=localStorage.getItem(KEY);}catch{}const saved=save();modal.close();render();notify(saved?'Backup restored on this device.':'Backup loaded into this tab. Browser storage is unavailable; export before closing.');}
  if(a==='export-raw'){try{download(localStorage.getItem(KEY)||'{}','physio-stored-data-recovery.json');}catch{notify('The browser is blocking access to stored data.');}}
});
document.addEventListener('change',e=>{const id=e.target.id;
  if(id==='scope-year'||id==='scope-semester'){state.settings[id==='scope-year'?'year':'semester']=Number(e.target.value);save();render();}
  if(id==='stream-select'){state.settings.stream=e.target.value;save();render();}
  if(id==='recall-course')go('recall',e.target.value?{course:e.target.value}:{});
  if(id==='quiz-course')go('quiz',e.target.value?{course:e.target.value}:{});
  if(id==='notes-course')go('notes',e.target.value?{course:e.target.value}:{});
  if(id==='notes-outcome')filterNotes();
  if(id==='recall-outcome'||id==='quiz-outcome'){const selection=Object.fromEntries(route().params);if(e.target.value)selection.outcome=e.target.value;else delete selection.outcome;go(id==='recall-outcome'?'recall':'quiz',selection);}
  if(id==='resource-type')filterResources();
  if(id==='timer-length'){timer.duration=Number(e.target.value);resetTimer();}
  if(id==='import-file')importFile(e.target.files[0]);
  if(e.target.dataset.task){const t=state.tasks.find(t=>t.id===e.target.dataset.task);if(t){t.done=e.target.checked;save();render();}}
});
document.addEventListener('input',e=>{const id=e.target.id;if(id==='recall-draft'&&session){session.draft=e.target.value;persistActive();}if(id==='course-search')filterCourseMap(e.target.value);if(id==='notes-search')filterNotes();if(id==='resource-search')filterResources();if(e.target.dataset.reflection){state.mistakes[e.target.dataset.reflection].reflection=e.target.value;save();}});
document.addEventListener('submit',e=>{const f=e.target;if(!['note-form','card-form','task-form','settings-form','station-form'].includes(f.id))return;e.preventDefault();
  if(f.id==='note-form'){const note={id:f.dataset.id||uid('note'),course:$('#note-course').value,title:$('#note-title').value.trim(),cue:$('#note-cue').value.trim(),body:$('#note-body').value.trim(),summary:$('#note-summary').value.trim(),updated:Date.now()};if(!note.title||!note.body){notify('Add a title and your explanation.');return;}const index=state.notes.findIndex(n=>n.id===note.id);if(index>=0)state.notes[index]=note;else state.notes.unshift(note);save();modal.close();noteTab='personal';if(route().page==='notes')render();else go('notes');notify('Note saved to your study desk.');}
  if(f.id==='card-form'){const card={id:uid('custom'),course:$('#custom-course').value,topic:$('#custom-topic').value.trim(),question:$('#custom-question').value.trim(),answer:$('#custom-answer').value.trim(),source:'user',wrong:[]};if(!card.topic||!card.question||!card.answer){notify('Add a topic, question and answer.');return;}state.customCards.push(card);save();modal.close();render();notify('Your card is ready in this course’s recall queue.');}
  if(f.id==='task-form'){const title=$('#task-title').value.trim();if(!title)return;state.tasks.push({id:uid('task'),title,course:$('#task-course').value,date:$('#task-date').value,done:false});save();render();notify('Study task added.');}
  if(f.id==='settings-form'){state.settings={year:Number($('#settings-year').value),semester:Number($('#settings-semester').value),stream:$('#settings-stream').value,newLimit:Number($('#settings-limit').value),timezone:$('#settings-timezone').value};save();render();notify('Your study settings are saved.');}
  if(f.id==='station-form'){const s=stations.find(s=>s.id===f.dataset.id);state.stationLogs.push({station:s.id,at:Date.now(),checked:document.querySelectorAll('[name="station-check"]:checked').length,total:s.checks.length,reflection:$('#station-reflection').value.trim()});save();notify('Practical reflection saved.');stationId=null;render();}
});
async function offlineStatus(){const el=$('#offline-status');if(!el)return;el.textContent='serviceWorker' in navigator?(navigator.serviceWorker.controller?'Offline cache active on this device.':'Offline cache will become active after the first successful load.'): 'Offline installation is not supported in this browser.';}
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').then(()=>offlineStatus()).catch(()=>{if($('#offline-status'))$('#offline-status').textContent='Offline cache unavailable. The app still works online.';});
window.addEventListener('storage',e=>{if(e.key===KEY){storageBlocked=true;loadError='Study data changed in another tab. Reload before continuing, or export this tab’s data first.';$('#save-status').textContent='! Another tab changed data — reload';notify(loadError);}});
function renderPrivacy(){main.innerHTML=heading('Study Desk privacy')+`<section class="panel cloud-account"><h2>Your study records</h2><p>Study Desk saves your notes, cards, review history, quizzes, tasks, settings and unfinished sessions in this browser. Google sign-in is optional. If you enable sync, those records are sent directly to a private app folder in your Google Drive. GitHub Pages serves the app.</p><h2>Google account access</h2><p>Study Desk uses your Drive account identifier and available display name or email to identify the connected account. The app requests access to its own Google Drive app data. The short-lived access token is held in the current page. Older sync versions are retained to protect against simultaneous edits.</p><h2>Control your copies</h2><p>Sign out in Account &amp; sync to stop syncing in this tab. To remove cloud saves, use Google Drive’s Manage Apps settings to delete Study Desk’s hidden app data. Local copies can be backed up in Settings &amp; backup and removed by clearing this site’s browser data. Diagram exercises and PDFs are stored separately on this device.</p><a href="#account">Back to Account &amp; sync</a></section>`;}
const cloudAccount=createCloudAccount({
  esc,heading,notify,exportBackup,
  getLocal(){
    if(storageBlocked || localStorage.getItem(KEY)!==lastPersisted)return null;
    return {snapshot:JSON.stringify(validateBackup(state)),marker:lastPersisted};
  },
  mayApply:()=>route().page==='account'&&!modal.open,
  applyLocal(snapshot,marker){
    if(storageBlocked||lastPersisted!==marker||localStorage.getItem(KEY)!==marker)return false;
    const next=validateBackup(JSON.parse(snapshot));
    try{localStorage.setItem(KEY,snapshot);}catch{return false;}
    lastPersisted=snapshot;
    state=next;
    session=null;
    quiz=null;
    render();
    return true;
  }
});
const learningTools=createLearningTools({$: $,esc,main,heading,courses,lessons,sources,anatomyOutcomes,allCards,cardById,sourceLink,save,render,go,notify,openModal,icon,reviewQueue,scheduleCard,recordMistake,currentCards,state:()=>state,resumeSession,showLesson:id=>{const l=lessons.find(l=>l.id===id);noteTab='library';go('notes',{course:l.course,lesson:id});},showPersonalNotes:()=>{noteTab='personal';go('notes');render();}});
render();if(loadError)notify(loadError);

document.addEventListener('click',event=>{for(const menu of document.querySelectorAll('.nav-group[open],.about-desk[open]'))if(!menu.contains(event.target))menu.open=false;});
document.addEventListener('keydown',event=>{if(event.key==='Escape')for(const menu of document.querySelectorAll('.nav-group[open],.about-desk[open]')){menu.open=false;menu.querySelector('summary').focus();}});
